const incoming = $input.first()?.json ?? {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const transaction_id = String(body.transaction_id ?? '').trim().toUpperCase();

const errors = [];
if (!/^TXN-\d{5}$/.test(transaction_id)) errors.push('transaction_id debe tener formato TXN-00000.');

return [{json:{valid:errors.length===0, transaction_id: $input.first().json.body.transaction_id}}];

